INSERT INTO feature VALUES('two-layouts-one-code','layouts','Two layouts of one code',NULL,'partial','uncommon','mainstream languages','A data type''s memory layout is a second data type over the same code, admitted by an equivalence with it whose round trips are proved by recursion and replayed by the kernel (Baudon''s Ribbit, Example 3.4): a list of `i32` laid out pointer-tagged and packed two elements per pointer is each layout by `ua`, a value moves from one layout to the other along their composite, formed at the transport until a named one checks (#2995), and `length`, written once over the list, runs on both by transport. A layout that loses elements is refused at its round trip. The layouts are data, not bytes: no memory type is a value yet, code emitted from a layout stands outside the trust boundary, and `equiv` decides no round trip over a type that holds itself (#1316).',NULL,'corpus/model/layouts/ribbit-list.gandr corpus/pathological/layouts/ribbit-list.gandr','corpus/ledger/features/two-layouts-one-code.gandr','#1316 #2804 #2805 #2995');
